export const tasks = applyDocumentationProgress(new TaskCatalogBuilder({ epics, workPackages: initialWorkPackages }).build());
export const workPackages = initialWorkPackages.map((item) => {
  const subtasks = tasks.filter((task) => task.workPackageIds.includes(item.id));
  const ownIds = new Set(subtasks.map((task) => task.id));
  return {
    ...item,
    status: "planned",
    due: [item.due, ...subtasks.map((task) => task.due)].sort().at(-1),
    covers: [...ownIds],
    dependencies: [...new Set(subtasks.flatMap((task) => task.dependencies))].filter((id) => !ownIds.has(id)),
  };
});
export const streams = roadmapBlocks.map((stream) => ({
  ...stream,
  workPackageIds: stream.taskIds,
  taskIds: tasks.filter((task) => task.streamId === stream.id).map((task) => task.id),
}));
export const projectPlan = new ProjectPlan({ types, tasks, streams, workPackages, epics });
